# The manual prints special-coil identities SP1 through SP6, not PinMAME public
# addresses. s11.c's PIA comments identify handler indices 0-5 as SP6, SP5, SP2,
# SP3, SP1 and SP4; applying the Data East offsets gives the public mapping below.
_SPECIAL_DE_PERMUTATION = (3, 4, 5, 1, 0, 2)
_SPECIAL_PIA_HANDLER_TO_PRINTED = {0: "SP6", 1: "SP5", 2: "SP2", 3: "SP3", 4: "SP1", 5: "SP4"}
_SPECIAL_PUBLIC_TO_PRINTED = {17 + _SPECIAL_DE_PERMUTATION[handler]: printed for handler, printed in _SPECIAL_PIA_HANDLER_TO_PRINTED.items()}
_SPECIAL_COILS_BY_PRINTED_NUMBER = {
    row["printed_number"]: row
    for row in (TRANSCRIPTION["coils"][str(address)] for address in range(17, 23))
}
_COILS = (
    {address: row for address, row in TRANSCRIPTION["coils"].items() if not 17 <= int(address) <= 22}
    | {str(public): _SPECIAL_COILS_BY_PRINTED_NUMBER[printed] for public, printed in _SPECIAL_PUBLIC_TO_PRINTED.items()}
)
# Publish one corrected transcription object. The raw JSON's 17-22 keys are storage slots for
# printed SP1-SP6 rows, not public addresses; consumers never see that sequential intermediate.
TRANSCRIPTION = {**TRANSCRIPTION, "coils": _COILS}
