_resolved_ids = {item["id"] for item in resolved_devices}
_centroid_devices = {"drag-point-centroid": [], "object-group-centroid": []}
for collection_name, prefix in (("switches", "switch.matrix"), ("outputs", "coil.driver"), ("lamps", "lamp.matrix")):
    for address, records in RESOLUTION[collection_name].items():
        device_id = f"{prefix}-{address}"
        if device_id not in _resolved_ids:
            continue
        origins = {record.get("origin") for record in records}
        if "drag-point centroid" in origins:
            _centroid_devices["drag-point-centroid"].append(device_id)
        if "object-group centroid" in origins:
            _centroid_devices["object-group-centroid"].append(device_id)
_computed_devices = sorted(device for devices in _centroid_devices.values() for device in devices)
_placement_count = sum(item["placements"] for item in resolved_devices)

